  sort_order, status, published_at, seo_title, seo_description)
values ('web', 'Business Websites', 'business-websites', 'A site that explains, persuades and converts.', 'Business Websites That Turn Visitors Into Inquiries', 'Your website is often the first serious conversation a customer has with you. We design and build business websites that explain what you do in seconds, earn trust and make the next step obvious.', 'globe', array['Messaging and page structure', 'Custom design (no purchased templates)', 'Responsive development on a modern framework', 'Content management for your team', 'On-page SEO, schema and XML sitemap', 'Analytics and conversion tracking', 'Accessibility checks against WCAG 2.2 AA', 'Redirects from your old site to protect rankings']::text[],
