insert into public.services (pillar, name, slug, short_description, hero_heading, intro, icon, features,
  sort_order, status, published_at, seo_title, seo_description)
values ('web', 'Web Applications', 'web-applications', 'Portals, platforms and internal tools.', 'Web Application Development for Portals, Platforms and Tools', 'When spreadsheets, email threads and off-the-shelf software stop fitting how you work, a web application can. We design and build customer portals, booking systems, SaaS products and internal tools that are fast, secure and easy to use.', 'layout-dashboard', array['Discovery and workflow mapping', 'UX design and clickable prototypes', 'Front-end and back-end development', 'Authentication, roles and permissions', 'Integrations via APIs and webhooks', 'Admin dashboards and reporting', 'Automated testing and deployment', 'Hosting, monitoring and backups']::text[],
