values ('web', 'UI/UX Design', 'ui-ux-design', 'Interfaces people understand in seconds.', 'UI/UX and Product Design People Understand in Seconds', 'Interfaces your users understand in seconds and enjoy coming back to. We research how people use your product, design flows that remove friction and hand over designs our own engineers can build without guesswork.', 'palette', array['User research and usability testing', 'Information architecture and user flows', 'Wireframes and clickable prototypes', 'Visual and interaction design', 'Design systems and component libraries', 'Accessibility review (WCAG 2.2 AA)', 'Developer-ready handoff in Figma']::text[],
