  sort_order, status, published_at, seo_title, seo_description)
values ('web', 'Custom Solutions', 'custom-solutions', 'Software shaped around your workflow.', 'Custom Software Development for Problems Off-the-Shelf Tools Don''t Solve', 'Got a business problem? We''ll build the solution. From business dashboards and internal tools to customer-facing calculators and full digital products, we build custom software around how your business actually runs.', 'layers', array['Business dashboards and reporting', 'Internal tools and admin panels', 'Calculators, finders and eligibility checkers', 'API development and third-party integrations', 'Data pipelines and automated reports', 'Digital product design and launch']::text[],
  50, 'PUBLISHED', '2026-10-04T00:00:00Z', 'Custom Software Development & Business Dashboards | Pytron Digital', 'Custom software development for problems off-the-shelf tools don''t solve: business dashboards, internal tools, calculators, integrations and digital products.')
