  sort_order, status, published_at, seo_title, seo_description)
values ('ai', 'Business Automation', 'business-automation', 'Connect tools and stop copy-pasting.', 'Business Automation That Connects Your Tools', 'Most teams lose hours to copying data between tools, chasing updates and sending the same messages. We connect your systems so information moves on its own — and every lead, order and request gets handled on time.', 'workflow', array['Lead capture and routing automation', 'CRM setup and integration (HubSpot, Zoho, Pipedrive and others)', 'Order, invoice and fulfillment workflows', 'Approval and notification flows', 'Scheduled reports and alerts', 'WhatsApp, Slack and email notifications', 'Documentation and monitoring']::text[],
  20, 'PUBLISHED', '2026-10-04T00:00:00Z', 'Business Automation Services — Workflow & CRM Automation | Pytron Digital', 'Business automation that connects your CRM, forms, store, accounting and chat tools: lead routing, follow-ups, approvals and reports that run without manual work.')
