  sort_order, status, published_at, seo_title, seo_description)
values ('ai', 'AI Integrations', 'ai-integrations', 'Assistants and AI features in your product.', 'AI Integrations That Make Your Product and Website More Useful', 'We add AI where it genuinely helps your customers or team: assistants that answer from your own approved content, AI features inside your web app, and secure connections between AI models and the systems you already run.', 'plug', array['Website and in-app assistants grounded in your content', 'Retrieval over documents, help centers and databases', 'AI search and recommendations', 'Summarization and drafting features', 'Integration with CRM, helpdesk and messaging', 'Evaluation, monitoring and cost controls']::text[],
  40, 'PUBLISHED', '2026-10-04T00:00:00Z', 'AI Integrations — Assistants, Chatbots & AI Features | Pytron Digital', 'AI integrations for websites and products: assistants that answer from your own content, AI features inside your app and connections between AI models and your systems.')
